                    "name": fix["name"],
                    "version": fix["version"],
                    "recommended_version": fix["recommended_version"],
                    "advisory_count": fix["advisory_count"],
                }
            )

    return _json_response(
        start_response,
        "200 OK",
        entries,
        trailing_newline=True,
    )

